    public static string Manifest(byte[] bytes,int chunk)=>TextNormalizer.Hash(string.Join("\n",Enumerable.Range(0,(bytes.Length+chunk-1)/chunk).Select(i=>$"{i}:{Math.Min(chunk,bytes.Length-i*chunk)}:{Hash(bytes.Skip(i*chunk).Take(chunk).ToArray())}")));
