        yield return ("2D WebVTT bounded validation parent binding private ownership and pending subtitle publication gate",async()=>
        {
            var good=System.Text.Encoding.UTF8.GetBytes("WEBVTT\n\n00:00:00.000 --> 00:00:01.000\nTest "+Guid.NewGuid()+"\n");Assert(VideoSubtitleService.Validate(good)==1,"Valid plain VTT rejected.");
            foreach(var bad in new[]{"WEBVTT\n\n00:00:00.000 --> 00:00:01.000\n<script>unsafe</script>","WEBVTT\n\nSTYLE\nbody{}","WEBVTT\n\n00:00:01.000 --> 00:00:00.000\nreversed","WEBVTT\n\n00:00:00.000 --> 00:00:01.000 align:left\nsettings"}){try{VideoSubtitleService.Validate(System.Text.Encoding.UTF8.GetBytes(bad));throw new Exception("Unsafe VTT accepted.");}catch(MediaUploadException){}}
            try{VideoSubtitleService.Validate(new byte[VideoSubtitleService.MaximumBytes+1]);throw new Exception("Oversized VTT accepted.");}catch(MediaUploadException){}
            var videoConfig=Config(config);var storage=StorageOptions.FromConfiguration(videoConfig);var vo=VideoOptions.FromConfiguration(videoConfig,"Development");await using var db=new PortalDbContext(options);var user=await InquiryFinishTests.User(db,Permissions.All,"Phụ đề SQL Test");var actor=await new CurrentPermissionService(db).GetAsync(user);var flow=new WorkflowService(db,new(),MediaUploadOptions.FromConfiguration(videoConfig,"Development"),storage);var c=await flow.SaveAsync(null,new(){Kind=ContentKind.Video,Title="VTT Test "+Guid.NewGuid(),BodyHtml="<p>Test</p>",PrimaryCategoryId=75},actor,null,Guid.NewGuid());
            var fixture=Environment.GetEnvironmentVariable("LandPortal__VideoFixture")!;var bytes=(await File.ReadAllBytesAsync(fixture)).Concat(Guid.NewGuid().ToByteArray()).ToArray(); // distinct pending-only ACL fixture; not a positive codec/engine assertion
var uploads=new VideoUploadService(db,storage,vo,new(db));var s=await uploads.CreateAsync(c.ContentId,user,"track.webm","video/webm",bytes.Length,Manifest(bytes,vo.ChunkBytes));for(int i=0;i<s.ChunkCount;i++){var part=bytes.Skip(i*s.ChunkBytes).Take(s.ChunkBytes).ToArray();await uploads.ChunkAsync(s.Id,user,i,Hash(part),new MemoryStream(part));}s=await uploads.CompleteAsync(s.Id,user);
            var service=new VideoSubtitleService(db,storage,vo,new(db));var track=await service.UploadAsync(s.MediaAssetId!.Value,user,"subtitle.vtt",new MemoryStream(good));Assert(track.State==InquiryScanState.NotScanned&&track.Original.IsQuarantined,"Upload manufactured Clean.");var repeat=await service.UploadAsync(s.MediaAssetId.Value,user,"subtitle.vtt",new MemoryStream(good));Assert(repeat.MediaAssetId==track.MediaAssetId,"Repeated subtitle duplicated immutable file.");Assert(!await VideoSubtitleService.ReadyAsync(db,storage,track.MediaAssetId,true),"Pending track Ready.");
            try{await flow.SaveAsync(c.ContentId,new(){Kind=ContentKind.Video,Title="No parent VTT",BodyHtml="<p>Test</p>",PrimaryCategoryId=75,Assets=[new(){MediaAssetId=track.MediaAssetId,Usage="Subtitle"}]},actor,c.RowVersion,Guid.NewGuid());throw new Exception("VTT without same-revision video accepted.");}catch(InvalidOperationException e){Assert(e.Message.Contains("Phụ đề phải"),"Unexpected failure hid parent guard.");}
            var stranger=await InquiryFinishTests.User(db,Permissions.All,"Khác phụ đề Test");try{await service.UploadAsync(s.MediaAssetId.Value,stranger,"subtitle.vtt",new MemoryStream(good));throw new Exception("Foreign VTT upload accepted.");}catch(MediaUploadException e){Assert(e.StatusCode==404,"Foreign video existence disclosed.");}
        });
    }
    // Orchestration-only negative injection. It cannot produce Clean/Ready and is not engine evidence.
    private sealed class NegativeScanner(bool release=false):IInquiryScanner
    {
        public TaskCompletionSource Entered {get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource Release {get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Task<(bool Ready,string Code)> HealthAsync(CancellationToken ct=default)=>Task.FromResult((false,"NEGATIVE_ONLY_FAULT"));
        public async Task<InquiryScanResult> ScanAsync(Stream stream,CancellationToken ct=default){Entered.TrySetResult();if(!release)await Release.Task.WaitAsync(ct);return new(InquiryScanState.ScanFailed,"NEGATIVE_ONLY_FAULT",null);}
    }
}
